contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dep) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= dep);
        uint256 balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBefore = address(c).balance;
        bool withdrew;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrew = false;
        } else {
            withdrew = true;
        }
        uint256 balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cAfter = address(c).balance;
        assert((!withdrew && balAfter == balBefore && cAfter == cBefore) || (withdrew && balAfter == 0 && cBefore - cAfter <= balBefore));
    }

    receive() external payable {}
}

