pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 dep) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep);
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 cBefore = address(c).balance;
        bool withdrew;
        try c.withdraw() {
            withdrew = true;
        } catch {
            withdrew = false;
        }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint256 cAfter = address(c).balance;
        assertTrue((!withdrew && balAfter == balBefore && cAfter == cBefore) || (withdrew && balAfter == 0 && cBefore - cAfter <= balBefore));
    }

    function testFuzz_run(uint256 dep) public {
        _run(dep);
    }

    receive() external payable {}
}
